// CSD_RATIONALE_BEGIN
// Penalty-and-rollback span strategy targeting the two primary failure clusters.
//
// From prior attempt analysis:
//   - 9 examples: malformed/unterminated spans with "=!!!!!!!" or ">!!!!!!!"
//     Root cause: grammar allows "=", "!" as valid expression tokens; model exploits
//     these when confused, entering a repetition dead-end.
//   - 4 examples: span open, no content, EOS or dead-end before ">>".
//   - 20 examples: syntactically valid but semantically wrong expressions.
//
// Design:
//   Outside spans: free UnconstrainedStep until RenderedEndsWith "<<".
//
//   Inside spans (normal budget):
//     (a) CloseSpanIfComplete — costs 0 if span is not yet complete, 1 if it closes.
//     (b) If not closed and validCount==0 (true dead-end): RollbackConstrainedToComplete
//         (0 cost) to last complete/empty prefix, charge 1 step.
//     (c) If not closed and validCount>0: AdaptiveConstrainedStepWithPenalties with
//         heavy penalty (10.0) on ["=","!","?","\\"] — these are the dead-end tokens
//         observed in failures. Hard parser mask still applies.
//     Every constrained branch increments steps by exactly 1.
//
//   Budget guard: when remaining <= closeReserve (150) inside a span, call
//     CloseSpanWithinBudget which is dead-end-aware and tracks the longest
//     completable prefix, emitting ">>" before the budget expires.
//
//   Final cleanup: same budget-guarded close after loop exit.
//
//   Prompt guidance: emphasize no "=" inside spans, use int(), keep variable names,
//     don't simplify expressions.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (budget guard / final cleanup): CloseSpanWithinBudget postcondition:
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (outside span, RenderedEndsWith "<<"): currentConstrainedOut := [] satisfies
//     IsValidPrefix([]) by method precondition. Otherwise insideConstrainedOut
//     stays false (implication vacuous). ✓
//
//   (inside, CloseSpanIfComplete closes): insideConstrainedOut becomes false,
//     implication vacuously true. currentConstrainedOut := [] by helper. ✓
//
//   (inside, dead-end rollback): RollbackConstrainedToComplete postcondition
//     asserts parser.IsValidPrefix(rc). insideConstrainedOut unchanged (still true). ✓
//
//   (inside, normal step): AdaptiveConstrainedStepWithPenalties returns EOS or a
//     parser-valid next token (hard mask postcondition). AppendConstrainedToken
//     postcondition: parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (outside, non-EOS): steps += 1, append exactly one token. ✓
//
//   (inside, CloseSpanIfComplete closes, cost=1): steps += 1; CloseConstrainedSpan
//     appends at most one ">>" token. |generated|+1 <= |generatedPrefix|+steps+1. ✓
//
//   (inside, dead-end rollback, cost=0): RollbackConstrainedToComplete only shortens
//     generated (|rg| <= |generated|). steps += 1. Invariant preserved. ✓
//
//   (inside, normal step, cost=1): steps += 1; AppendConstrainedToken appends one token
//     on non-EOS path (break on EOS with no append). ✓
//
//   (budget guard): CloseSpanWithinBudget(remaining) cost <= remaining;
//     |cg| <= |generated| + remaining <= |generatedPrefix| + steps + remaining
//     = |generatedPrefix| + maxSteps. After steps := maxSteps: invariant holds. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate and final symbolic expression in << >> delimiters. " +
  "Inside << >> write ONLY the symbolic expression — no equals sign, no explanation text, no units. " +
  "Use only: numbers, variable names, +, -, *, /, //, %, (), int(). " +
  "Wrap products or divisions that must produce a whole number with int(). " +
  "Use // for integer (floor) division. " +
  "Keep variable names EXACTLY as given in the problem — do NOT substitute numbers for variables. " +
  "Do NOT write = inside << >>. Do NOT simplify or factor. " +
  "The final line must be: The final answer is <<symbolic expression>>.");

var closeReserve: nat := 150;
var badTokens: seq<Token> := ["=", "!", "?", "\\"];
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close with dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    // Inside a constrained span —
    // Step 1: try to close if already complete (0-cost when not complete)
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // Step 2: check for true dead-end (no valid continuations)
      var validCount := helpers.ValidTokenCount(parser, currentConstrainedOut);
      if validCount == 0 {
        // True dead-end: roll back to last complete or empty prefix (0 cost)
        var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
        generated := rg;
        currentConstrainedOut := rc;
        steps := steps + 1;
      } else {
        // Step 3: generate next constrained token with heavy penalty on dead-end tokens
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.AdaptiveConstrainedStepWithPenalties(
          lm, parser, constrainedPrompt, currentConstrainedOut,
          validTokenGroups, 4.0, badTokens, 10.0, 12, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var ag, ai, ac := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }
}

// Final cleanup: force-close any remaining open span with leftover budget
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

